f as (select s.*, to_char(kwc,'FM9G999G999') k, to_char(round(kwc*0.95),'FM9G999G999') p, to_char(m2,'FM9G999G999') m from s),
ins as (
  insert into public.amb_leads (id, wave, priority, name, address, municipality, solar_kwp, production_mwh, companies, owner,
    target_role, pitch, target_function, lat, lng)
  select id, 3, prio, name, address, muni, replace(k, ',', ' ') || ' (détecté)', round(kwc*0.95), companies, owner,
    'Producteur (priorité)',
    'Installation photovoltaïque d’environ ' || replace(k, ',', ' ') || ' kWc détectée sur la toiture (≈ ' || replace(m, ',', ' ')
      || ' m² de panneaux), soit près de ' || replace(p, ',', ' ') || ' MWh par an. Ce qui n’est pas consommé sur place part aujourd’hui sur le réseau : CityWatt peut le valoriser auprès de consommateurs bruxellois voisins.',
    'Gérant, responsable technique ou énergie', lat, lng
  from f on conflict (id) do nothing returning id),
st as (
  insert into public.amb_lead_status (lead_id, status)
  select id, trim('Batch installations PV (sept. 2026) — pas encore approché. ' || note) from s
  on conflict (lead_id) do nothing returning lead_id)
select (select count(*) from ins) leads_ajoutes, (select count(*) from st) statuts;
